// The app's version and what changed in each, newest first: shown small at the top right of the home
// screen (tap it for this list). One version per update that went out (the number counts them).
// Add an entry at the top with each update.

/** @type {{ v: string, date: string, notes: string }[]} */
export const HISTORY = [
  { v: '3.61', date: '2026-11-28', notes: 'Video Editor → 📱 Socials Frame: 📤 Make a Socials post. Under a finished video, pick the account and caption, and it\'s put in Socials as a draft on that account, ready for you to share there.' },
  { v: '3.60', date: '2026-11-28', notes: 'Video Editor → 📱 Socials Frame: wrap a video as a 📖 story, 🖼 feed post, 🎬 short video or 📞 video call (the app\'s own designs in those familiar shapes), with your name, picture, caption, likes and comments, or the caller\'s name and a running call timer. It finds the faces and keeps the people in frame as it crops, and every video comes out the same: 1080 × 1920 portrait MP4 with its sound. A preview shows how it will look.' },
  { v: '3.59', date: '2026-11-28', notes: 'Video Editor: trim on a timeline (drag the two handles over a strip of the video\'s frames), put text on a video (top, middle or bottom, three sizes, five colours), make it faster or slower (¼× slow motion to 4×), and 🎞 GIF turns a part (up to 15 s) into a looping GIF. 2D → 3D trims on the timeline too. Socials\' built-in replies are fuller: each account remembers what you\'ve told it (your dog\'s name, your sister, where you work or live, what you love) and asks after it later, talks about what it\'s into (from its profile), and more often adds a bit of its own and a question to keep the chat going.' },
  { v: '3.58', date: '2026-11-27', notes: 'Socials: AI replies are removed on iPhone and iPad (even the smaller model needed more memory than Safari gives a page and closed the app). Replies there come from the built-in engine, the leftover model files are deleted to free the space, and the Language slider stops at Adult (Explicit was for the AI\'s writing). On a computer, AI replies stay as they were.' },
  { v: '3.57', date: '2026-11-27', notes: 'Socials on iPhone: ⚡ fast natural voices. The full voices took over a minute per line on a phone and fell back to the robot voice; now an iPhone or iPad uses 13 fast natural voices (about 80 MB, once) that start speaking in a second or so. Each account keeps the fast voice most like its own, and Nova stays Nova (crisp and polished). Switch between ⚡ Fast and 🎙 Full in Sync and password. AI replies: an iPhone or iPad now downloads a smaller model (480 MB instead of 1.2 GB), which fits in Safari\'s memory, and a load that crashed is never retried by itself.' },
  { v: '3.56', date: '2026-11-27', notes: 'Fix: on iPhone, playing a voice could close Socials ("A problem repeatedly occurred"): the natural voices used the graphics chip, which takes more memory than Safari allows. On iPhone and iPad they\'re back on the processor (a switch in Sync and password turns the graphics chip on, if you\'d like to try it); a load that didn\'t finish is never tried the same way again; and opening a chat no longer loads the voices by itself.' },
  { v: '3.55', date: '2026-11-27', notes: 'Socials group chats: Messages → 👥 New group, pick two or more accounts and give it a name if you like. When you say something, one, two or three of them answer in turn, each typing first with its name over its message, in its own way and (while you\'re chatting) read aloud in its own voice. Groups show in Messages with what\'s unread; tap the name to rename it, see who\'s in it, or leave it.' },
  { v: '3.54', date: '2026-11-27', notes: 'Socials\' Language slider has a fifth step, Explicit (18+): the on-device AI\'s messages, comments and captions can be fully uncensored between consenting adults, sexual talk included (every account is a made-up adult). Accounts marked ⭐ Celebrity stay at Adult at most.' },
  { v: '3.53', date: '2026-11-27', notes: 'Socials: while you\'re chatting (for two minutes after you send a message), replies play by themselves as they come, one after another; opening a chat never plays anything by itself (Sync and password → Play replies while chatting). Voices made are kept on the phone, encrypted like the rest of Socials, so a message played again plays at once, even the next day. The Language slider now applies to captions too, up to Adult (every account is a made-up adult).' },
  { v: '3.52', date: '2026-11-27', notes: 'Socials\' natural voices, faster: trying voices out (the voice picker\'s ▶ and Edit profile\'s ▶ Preview) now plays at once, from a sample of each voice kept with the app, and the picker lists all 43 natural voices to hear before you download them. Messages: the voices run on the phone\'s graphics chip when it can (several times faster), replies are made while they\'re "typing" and the newest message as a chat opens, and anything played is kept for a while, so its 🔊 plays at once. A long wait no longer drops to the robotic phone voice so soon. Tip in Settings: an iPhone\'s Enhanced or Premium voices speak instantly.' },
  { v: '3.51', date: '2026-11-27', notes: 'Socials read aloud, fix for messages on iPhone: when the audio player claimed to be playing but stayed silent, the voice now notices within a second and plays another way (and keeps using it). A 🔊 shows ⏳ while the voice is being made and lights up only once sound has really started; if nothing could be played, or a voice came out silent, a note says so instead of staying quiet. 🔊 Test now also says how the last line was played.' },
  { v: '3.50', date: '2026-11-27', notes: 'Files has a 🎬 Video Editor, all on this phone. ✂️ Edit: trim, crop (square, tall, wide…), resize, rotate, flip, keep, remove or replace the sound, play it backward, join clips, or save the sound alone. 🥽 2D → 3D turns a regular video into 3D for a VR headset like the Meta Quest (Skybox VR, DeoVR, Meta\'s player): side by side (full or half) or top and bottom, as an MP4 that keeps the frame rate, length and sound. An AI model on the phone (about 26 MB, downloaded once, then offline) works out how far away everything is; set the 3D strength, pop-out, steadiness, size per eye, swap eyes and trim, preview a frame (side by side, depth, red-cyan or cross-eye), and watch the frames count down with time left and Cancel. Each file made is checked before you get it, with how to watch it on a Quest next to it.' },
  { v: '3.49', date: '2026-11-27', notes: 'Socials messages: a chat now fills the screen like Messages does, its name at the top, the conversation in between and the text box right above the keyboard. Typing no longer shifts the screen or pushes earlier messages off the top, and the newest messages stay in sight when the keyboard opens.' },
  { v: '3.48', date: '2026-11-27', notes: 'Socials read aloud, second fix for iPhone: the natural voices now play through an ordinary audio player unlocked at your tap (the most dependable way on an iPhone), and the silent clip used to unlock sound is no longer blocked by the app\'s own security rules. 🔊 Test also lists what the sound can do on your phone, to help if it still doesn\'t play. Fixed: Socials\' recovery key (shown once, when it\'s first saved to Drive) could be lost by tapping a tab while it was on screen; it now stays until you tap I\'ve saved it.' },
  { v: '3.47', date: '2026-11-27', notes: 'Socials read aloud on iPhone: no sound came out, because an iPhone only lets a page start sound right at the tap and the voice was ready a few seconds later. Each 🔊, ▶ and Send now wakes the sound at the tap, it plays even with the silent switch on, and anything that can\'t be heard says why. New 🔊 Test (Sync and password → Natural voices) plays a line and says which voice played and how long it took.' },
  { v: '3.46', date: '2026-11-27', notes: 'Socials\' sports posts show players\' full names (never cut off) and a 🚫 OUT note under each team (who\'s out, from the injury report; before a primetime game, the whole report). Basketball minimums now include rebounds, stocks (steals + blocks) and 3-pointers made. 🔐 Admin is at the top of the Sports front\'s settings. Primetime NFL and NBA games also show in Sports and on the home screen\'s Updates card. Natural voices now use the full-quality model (the smaller one sounded metallic and was no faster; about 330 MB, offered again to download), the voice picker offers them right there, and an account\'s own phone voice is the best-sounding one, never a novelty or robotic one.' },
  { v: '3.45', date: '2026-11-27', notes: 'More speaking voices, each described in a few words: Edit profile → Speaking voice → Choose… shows every voice as a card (\"warm · polished · soft · transatlantic · woman\"), filtered by tapping those words (deep, British, calm…), by kind or by a search, with ▶ to hear each. 15 new natural blends (43 natural voices in all: transatlantic, very deep, androgynous and more, nothing more to download), a pitch setting (Deeper, Natural, Higher) for every voice, and this phone\'s voices described by accent and kind, its novelty voices included. Fixed: an account answering several comments on its post no longer says the same thing twice.' },
  { v: '3.44', date: '2026-11-26', notes: 'Socials reads aloud: a 🔊 on every message, comment and caption plays it in that account\'s own speaking voice, and new replies in a chat can be read out as they come. Pick each account\'s Speaking voice and speed in Edit profile (▶ Preview), from this phone\'s voices (more and better ones in iPhone Settings → Accessibility → Spoken Content → Voices) or, after a one-time download (about 105 MB, Sync and password → Natural voices), 28 natural-sounding voices, American and British. All on the phone and offline. Fixed: Saved Files\' 🔎 Search (and its shortcut) could be replaced by the file list a moment after opening.' },
  { v: '3.43', date: '2026-11-26', notes: 'Socials: each account can have its own Voice (hype, chill, warm, witty or classic) and what it\'s Into, in Edit profile: its comments, replies, captions and messages take that voice, and the AI writes as it from its bio and interests. Home-screen shortcuts (Android and computers; press and hold the icon): New Socials post, Socials messages, Search Saved Files, Scan files for faces.' },
  { v: '3.42', date: '2026-11-26', notes: 'Socials: your accounts reply to comments on their own posts (thanks, answers like where it was, banter back), in their own voice, shown under each comment; Reply under any comment to answer it (Sync and password → Replies to comments). AI captions are kept only when they\'re clearly better than the built-in ones. Saved Files: 🔎 Search by name, folder, kind, person and date, with pictures, offline too. Settings → Saved Files: back up the extras every week by itself (the newest 4 kept), and 📲 set up a new phone from your Drive with one password (Saved Files, Socials, the extras and the Vault).' },
  { v: '3.41', date: '2026-11-26', notes: 'Saved Files\' scanner learns: each ✓ It\'s them adds that face to the account (found more often, from more angles), and each ✕ Not them remembers it isn\'t that account, so it isn\'t suggested again. 👥 Unknown people (in ⚙ Character matches): faces that are none of your accounts, grouped by person across your scans, each with how many files it\'s in. ＋ Make a Socials account turns one into an account (its clearest face the profile photo; its files matched to it, and into its drafts if you like), and later scans know it; Not someone sets one aside. Socials\' suggested and automatic captions are written in the posting account\'s own voice (hype, chill, warm, witty or classic), by the AI too when it\'s on.' },
  { v: '3.40', date: '2026-11-26', notes: 'Saved Files\' 🔎 Scan for characters: each file shows its picture (a video four stills) and each suggestion the face found beside the account\'s profile photo, to check by. ✓ It\'s them puts the file on that account in Socials as a draft waiting for your OK (📥 above Socials\' feed: open it there and share it, or discard it) and marks the file 👤 @name in Saved Files (a file with several of your accounts in it matches each: the others join the same draft as collaborators), with chips to show one person\'s files (in ★ Favorites too). Photos and videos saved from the phone are scanned as they\'re saved. Matching is better: an account\'s posts count as well as its profile photo (a post with only its poster in it is them; in group posts each face goes to whoever it clearly is). Socials\' data is now encrypted on the phone with its password. Settings → Saved Files: back up the extras kept only on this phone (favorites, pictures, matches, backgrounds, the Dock, Socials\' and Sports\' settings), encrypted with a backup password, to Saved Files or the phone, and restore them. With 🤖 AI replies on, the AI also writes ✨ Generate\'s comments, new posts\' automatic comments and the captions, from what the photo shows, checked and falling back to the built-in engine.' },
  { v: '3.39', date: '2026-11-26', notes: 'The hidden area is now the Vault, opened from Files\' settings with the same password or Face ID. Saved Files has ★ Favorites: starred files as two columns of cards, each with its picture (a video\'s stills under it), your own title and description, dragged into the order you like and kept for offline. 🔎 Scan for characters reads photos and videos (many stills each) on the phone and suggests which Socials account a face might be; nothing is changed, and the matches you confirm are kept in Character matches. Background pictures of your own for Socials, each profile page and the Vault.' },
  { v: '3.38', date: '2026-11-26', notes: 'Socials, private and offline: no text you write or that\'s written back ever leaves the app. The AI replies\' engine is fenced off the network: it can only download its model\'s own files once, and after that it makes no outside requests at all (tested with the network blocked). Replies, comments, captions and photo and face reading all run on the phone and work offline.' },
  { v: '3.37', date: '2026-11-26', notes: 'Socials: 🤖 AI replies, an on-phone language model (about 1.2 GB, downloaded once, works offline) that writes the replies in messages from the whole conversation, in each account\'s voice (needs WebGPU: iPhone with iOS 26 or later). A Language slider from Tame to Adult (18+) sets how clean or crude replies and comments are. New posts recognize faces: anyone whose profile photo matches a face in the photo is added as a collaborator, for you to change before sharing.' },
  { v: '3.36', date: '2026-11-26', notes: 'Socials\' replies and comments adapt more and vary more. Each account has its own voice (hype, chill, warm, witty or classic, always the same), and replies follow how you text in that chat: lowercase, emojis or none, !!!, short, "lol"/"fr". Replies add something of their own ("I\'ve been craving tacos all week"), bring up things from earlier in the chat, sometimes come as two quick messages, and don\'t open or ask the same way twice. Comments have livelier lines ("Not the red dress being this good", "Frame this immediately").' },
  { v: '3.35', date: '2026-11-26', notes: 'Socials\' Sports front: nationally televised NFL and NBA games (like tonight\'s on NBC) post before they start, with their network and time, and a 📺 Primetime chip shows only those. NFL, college football and NBA posts list each team\'s players\' offensive stats, for those over the minimums you set in its ⚙ settings (100 passing, 25 rushing and 25 receiving yards, 10 points or 5 assists to start). The Dock\'s logo now floats above the Dock when it\'s open, not in it.' },
  { v: '3.34', date: '2026-11-26', notes: 'Socials: message replies now use your own words and build on them ("I got the job!" → "You got the job?! Congrats!! Tell me everything about the job"; "the weather is so nice" → "Agreed, the weather is so nice!"; "heading to Denver tomorrow" → "Denver tomorrow?! I love Denver. Who are you going with?"), fitting the kind of news (a win, something you tried, bad news), instead of stock lines.' },
  { v: '3.33', date: '2026-11-26', notes: 'Socials. Messages: when you message one of your accounts it replies by itself, from the whole conversation: it follows up on plans you mentioned ("How was the concert??"), answers when asked back, and never repeats itself. Videos: ✂︎ Frame video picks the part that shows and its shape, by dragging, zooming or dragging a corner to any size. Photos: drag a corner of the crop frame to any size. On the Owner account, ⋯ → Download post saves all of a post\'s files or the ones you pick. Accept All also clears those requests\' notifications, tapping a used hashtag again takes it back out, and comments mention more of what\'s in the post.' },
  { v: '3.32', date: '2026-11-25', notes: 'The Dock can be tucked away behind a small Command logo at the bottom left: tap it to open the Dock, and again to close it. Each app remembers (tap the logo, or Settings → Dock → Show the Dock in…); Socials starts tucked away. Socials: Accept All in Messages accepts every collab request at once.' },
  { v: '3.31', date: '2026-11-25', notes: 'Socials\' comments and captions fit the photo much better. It now reads what people wear (cap and gown, suits, swimsuits, coats, hoodies, sneakers, the main colour, summer or winter clothes, brand and team names on them), how many people there are and how they pose (arms up, hands on hips, sitting, head to toe, close-up), and the background on its own: a blue sky is no longer taken for a beach, and plain selfies no longer get "#ootd". Comments in a batch are each about something different, with different words and emojis. A caption is now written in for you from the most specific thing in the photo.' },
  { v: '3.30', date: '2026-11-25', notes: 'The Dock: a short bar along the bottom of every screen, with a Home button in the middle and two Favorites on each side, one tap to an app. Hold one down (or Settings → Dock) to choose its app. Socials: picking a video no longer makes it spill past the screen (the page shifted right and zoomed); the preview stays in its frame. Videos are read from several frames, not just one, plus an iPhone video\'s own time and place, for comments and captions.' },
  { v: '3.29', date: '2026-11-25', notes: 'Socials reads your photos, on the phone (nothing sent anywhere): what\'s in them (a dog and its breed, food, a beach, mountains, a car…), how many people, the light (a sunset, night, snow), and when and where they were taken. ✨ Generate\'s comments, and the comments left on a new post, now fit the photo as well as the caption ("Love the golden retriever", "You two are the cutest", "Boulder looks amazing"). New: ✨ Suggest caption when posting, with an emoji, the place and hashtags.' },
  { v: '3.28', date: '2026-11-25', notes: 'Socials: picking photos and videos is reliable (files from iCloud too): each is read in full as soon as it\'s picked and tried again by itself if it fails, with time for long videos, and listed with its own status (Loading %, Preparing, Ready ✓, or Try again). Drag ☰ to reorder them, when posting and in ⋯ → Edit, which can now also add files and remove them. Every new post tags the Owner. ✨ Generate makes 1, 3 or 5 comments at once, each made for the caption: the places, things, ages and questions in it, its hashtags and the people tagged.' },
  { v: '3.27', date: '2026-11-24', notes: 'Socials: a post with several videos plays them one after another in Reels (a bar for each at the top); from a profile, a post with several photos or videos opens to swipe through them; in a post, a video that ends goes on to the next. A progress bar while posting: preparing the files, saving, uploading each to Saved Files, Posted ✓.' },
  { v: '3.26', date: '2026-11-24', notes: 'Clock: each place over a picture of it (Colorado\'s mountains, the Golden Gate Bridge, the Statue of Liberty, Hawaii\'s palms, Big Ben, the Brandenburg Gate, Bran Castle…) with its sky as it is there now, and the time clear over it; the World Clock / Timer / Stopwatch tabs are one card in a line; the timer fits the phone\'s width. Units: an icon on each tab. Socials\' sports posts: readable in dark mode and on light team colors, with each team\'s stat leaders.' },
  { v: '3.25', date: '2026-11-24', notes: 'Socials opens to a Sports front: NBA, NFL, MLB, NHL and college football games become posts as they\'re played and when they end, each a card in the two teams\' colors with the score (live or final), the stat leaders and a caption, filtered by league and updated by themselves while it\'s open. Your own Socials is reached from its settings, behind its password or Face ID as before.' },
  { v: '3.24', date: '2026-11-24', notes: 'Two new apps in Productivity. Clock: a world clock (Colorado large at the top, then California, New York, Hawaii, London, Germany and Romania in two columns; + Add New, and Edit to reorder, change or remove), a Timer and a Stopwatch. Calculator: a standard calculator. Units has a Time Zone converter: a time in one place, in another.' },
  { v: '3.23', date: '2026-11-24', notes: 'Socials: accounts are Friends or Celebrities, listed apart under the Owner (in the same order as before), with + Add New right under the Owner instead of a form at the bottom. A new profile photo is also posted, whole as it was picked. The photo editor\'s Fit shows the whole photo with a frame you drag over it and pinch to zoom, with more shapes (3:4, Story 9:16, 16:9, 4:3) and Custom (your own width and height).' },
  { v: '3.22', date: '2026-11-24', notes: 'Storage, a new app in Productivity: all of the app\'s storage with pie charts. On this device: what each part takes (Socials, drawings, notes…, the files for offline use), against what the browser allows, each opening to its largest items, with Clear where it can safely go. Google Drive: your whole Drive and what\'s in it (Saved Files, Socials\' copy, the encryption keys, the rest of your Drive). How uploading to Drive is limited (25 MB a file, and why) and what encryption does to storage (almost nothing: about 0.4 KB a file), explained. Sizes from 1,000 MB on show in GB, here and in Settings.' },
  { v: '3.21', date: '2026-11-23', notes: 'Fashion: a short top or open jacket put on someone whose own top was longer no longer leaves a flat block of bare skin down to the bottom of the photo: below the bare midriff, what the piece\'s model wears there (a belt, jeans) comes with it, and the piece isn\'t faded out at the photo\'s bottom edge. Where the made skin meets their real neck above the old collar, no thin line or greyer band is left: the two blend smoothly across the edge.' },
  { v: '3.20', date: '2026-11-22', notes: 'Fashion: no thin red line left along the edge of their hair where it lay over a red part of what was worn, and the shade beside the neck there is a neutral shadow, not tinged with it.' },
  { v: '3.19', date: '2026-11-22', notes: 'Fashion: the piece\'s edges cast a soft shadow onto the skin made under them (its neckline, a short top\'s hem over a bare midriff, a jacket\'s open front), so the skin sits under the piece instead of looking cut out flat. A lace sleeve no longer leaves a flat blue patch past its hem: its model\'s arm seen through the lace is no longer taken for the lace.' },
  { v: '3.18', date: '2026-11-22', notes: 'Fashion, skin where it meets everything else: the tips of their hair over a colorful part of what was worn (a red stole) no longer stay red when it\'s taken off, and the shade beside the neck isn\'t tinted by it; the shoulders out past the neck are skin, not the old top\'s light rim (a pale band on a white top); made skin takes its color only from real skin that\'s skin-colored; an arm made bare is shaded round along the arm (darker toward both sides, also the side against the body), and the made skin\'s outer edge blends softly with what\'s behind them.' },
  { v: '3.17', date: '2026-11-22', notes: 'WorldAtlas: the Nether and End no longer show terrain that doesn\'t match Bedrock (a note says so; the Overworld biome map, which does match, stays). New: slime chunks (Bedrock\'s formula; shade them green on the map from Tools or Settings, and the readout says when you\'re in one), a portal planner in Tools (pick an Overworld spot for the exact Nether spot to build its portal, or back, with a warning when another portal nearby could be linked by mistake), and Overworld structures in the castle panel (villages, outposts, monuments, mansions, temples), learning from the ones you mark as found, as the Nether ones do, and only suggested where the biome allows them. On a phone the readout no longer sits under 📚 Tutorials.' },
  { v: '3.16', date: '2026-11-22', notes: 'Socials: the account list puts accounts with unread messages first (the most, then the latest), then the ones you used last, under the Owner. 👤 Tag and 🤝 Collab are small buttons that open their list (alphabetical) when tapped; inviting someone to collab tags them too. # Community when posting: hashtags used before, the most used first, a tap to add. ✨ Generate (Owner only, offline): a comment from another account (random, or one you pick) fitting the post\'s caption and emoji, and in a chat a reply from the other account to what you just sent.' },
  { v: '3.15', date: '2026-11-22', notes: 'Socials: 🔖 save posts to your own Saved tab (only you see it). 👁 views: each post counts how many times it\'s been seen, in the feed, in Reels or opened from a profile, by any account. Home and Reels now favor the most viewed, liked and newest posts: they\'re likelier to come up near the top.' },
  { v: '3.14', date: '2026-11-22', notes: 'Face ID (passkeys) as well as passwords: set it up in the hidden area (once it\'s open) or in Socials → Sync and password, and Face ID opens it; your passwords still work. On iOS 18 and later Face ID also lets Socials sync without typing its password. Settings → Storage now shows bars: what the app keeps on this device against the most the browser allows, a button to protect it from being cleared, your Google Drive\'s space (with the Saved Files script updated to version 5), and the app\'s own limits.' },
  { v: '3.13', date: '2026-11-22', notes: 'WorldAtlas Tutorials (📚, above Home): farm designs with video links and photos, a supply list of every block and how many (in stacks), the space each takes in blocks, and a 3D view you can turn and build up layer by layer. Draw your own a layer at a time, with a palette or any of ~700 blocks by search, or air. Starts with popular farms: wheat, pumpkin & melon, automatic sugar cane, iron, cobblestone generator and eggs.' },
  { v: '3.12', date: '2026-11-22', notes: 'Socials: Collab. Invite up to three of your other accounts when posting or editing (🤝 Collab): each gets a collab request in their messages to accept or decline; once accepted, the same post is on their profile and in their followers\' feeds too, shown as "you and them". A collaborator can remove themselves later.' },
  { v: '3.11', date: '2026-11-22', notes: 'Socials: Stories (posts from the last 24 hours, opened by tapping the ringed circle at the top of Home or on a profile), Drafts (save a post to finish later), pinned posts (up to three at the top of a profile), comments on each new post from three of your other accounts (the Owner can turn them off), hashtags (tap one for its posts; search them), ⬇ to download an account\'s photos and videos as a zip, and Recently deleted (deleted posts can be restored for 7 days).' },
  { v: '3.10', date: '2026-11-21', notes: 'Socials: post several photos and videos together (up to ten; pick them at once or add more, each photo through the editor), shown as a carousel you swipe through. Reels play in a shuffled order; pull down at the top to shuffle again (a video you just posted comes first).' },
  { v: '3.09', date: '2026-11-21', notes: 'Fashion, in proportion: a piece\'s sleeves no longer balloon into wings past the shoulders, and a side hidden in the piece\'s photo (an arm behind the person beside them) is made as a mirror image of its other side, whole, instead of strips, a gap and a sleeve sticking out. Sleeves end at their real hem: the model\'s arm below a short sleeve is no longer taken for more sleeve (it showed as dark bands). Made skin on arms is shaded round, as an arm is.' },
  { v: '3.08', date: '2026-11-21', notes: 'Fashion: seamless necklines where skin meets skin. The old collar\'s thin edge (a white collar\'s light line under the jaw) is replaced too; the made neck continues the real neck\'s width and warmth instead of turning greyer or wider below the collar, with no doubled chin shadow; made and real skin fade together over a few pixels. No more thin grey lines across the neck (a collar mistaken for straps, or a sliver of the piece\'s collar back) and no blotches from the piece model\'s skin.' },
  { v: '3.07', date: '2026-11-21', notes: 'Socials: tag your other accounts in a post (shown as "with @…", and in their Tagged grid), and @mentions in captions link to the account. Share a post in a DM with ✈ (it shows in the chat as a card that opens the post). On the Owner account, any photo post\'s ⋯ → Open in… sends a copy to the Photo Editor, FM or Fashion (as the person to dress or as the piece).' },
  { v: '3.06', date: '2026-11-21', notes: 'Socials: photos and videos are now kept on the phone in a way Safari on iPhone doesn\'t lose (some older uploads showed a broken picture after the app was reopened). Older uploads are moved over when Socials opens; any photo that can\'t be read says so on its post, and if it was saved to Saved Files it comes back from there at the next sync. Liking or commenting no longer rewrites every photo each time.' },
  { v: '3.05', date: '2026-11-21', notes: 'Socials offline: post, edit and message with no connection; it\'s all kept on the phone and saved to Saved Files by itself when you\'re back online. On the Owner account, Sync and password shows how many files are waiting to be saved (⏳ by the cloud at the top too), or ✓ when everything is; refreshing or closing the app before then loses nothing.' },
  { v: '3.04', date: '2026-11-21', notes: 'Socials, more of it. Photos (and profile photos) go through a photo editor first: fit them to how they\'re shown (Square, Portrait, Landscape or as they are; a circle for a profile photo; drag, pinch to zoom, turn), then the Photo Editor\'s filters and adjustments; nothing of it is kept in the Photo Editor. Edit a post\'s caption or photo later from its ⋯. Post videos, with their sound, and watch everyone\'s in the new Reels tab, one at a time, swiping up. Direct messages between your accounts (✈, with unread counts; answer as the other account). The Owner account (your first) is marked and always listed first when switching accounts.' },
  { v: '3.03', date: '2026-11-20', notes: 'Socials: its own password, set the first time and asked each time the app starts (☁ → Sync and password to change it or lock it now). With Saved Files set up, Socials is also kept in your Google Drive (a Socials folder in your Saved Files), encrypted on the phone with that password first, so your other devices open the same accounts, posts and photos with the same password; changes on either sync to the other. A recovery key, shown once, opens it if the password is forgotten.' },
  { v: '3.02', date: '2026-11-20', notes: 'Socials, a new app in Creativity: a photo feed laid out like the familiar photo apps, where everything is yours. Make accounts (username, name, bio, profile photo) and switch between them; post photos with captions from any of them; follow accounts from each other and see the posts of the ones you follow in Home; like (or double-tap) and comment; search accounts and browse every post as a grid; profiles with posts, followers and following. All kept on this phone and still there after a reload; nothing goes anywhere.' },
  { v: '3.01', date: '2026-11-20', notes: 'Fashion: realistic bare skin where the old top is taken off, instead of a flat fill. It\'s shaped as a body (round, darker toward the figure\'s outline, lighter on the side the light comes from, the collarbones and the hollow at the throat softly shaded), with their own skin\'s grain and no bands or blocks. Its color comes from their face when what looked like their body\'s skin wasn\'t (a hand, a lock of hair), so it no longer looks tanned or orange. Where the piece shows its model\'s skin (a neckline), that skin\'s real shapes come across too, in their skin tone. Their own hand over where the top was is left as it is.' },
  { v: '3.00', date: '2026-11-20', notes: 'Fashion, redesigned: Replace (a top, a dress, an upper body) now works one simple way. What\'s worn there is taken off to their own skin, then the piece is put on as one smooth whole, mapped body to body as a person is rigged: the torso by the chin, shoulders and hips, each sleeve along its own arm, blended at the shoulders, so there are no joins, strips or lines between parts. Only the piece\'s own cloth is laid on (not its model\'s skin, hair or anyone beside them), with its own colors and soft edges; a part hidden in its photo (behind the person beside them, an arm out of sight) is taken from its other side; a piece cut off by its photo is carried on to where the top worn there ends. The light, hair and hands in front, grain and edge shadows are matched to the photo as before.' },
  { v: '2.01', date: '2026-11-20', notes: 'Fashion, a piece from a group photo (one of two people, the other leaning in): laid on body to body, so the dress keeps its shape: its neckline open (their skin shows there), both shoulders covered (a shoulder hidden by the other person\'s hair in its photo is taken from its other side, mirrored), the other person\'s hair not copied in, its belt at the waist. Made skin\'s texture is never taken from a hand (knuckles and creases tiled into a weave) or from a white knit the finder took for skin; it comes from their cheeks then.' },
  { v: '2.00', date: '2026-11-20', notes: 'Fashion, a piece photographed turned (a three-quarter view) onto someone facing the camera: in proportion. It was sized by the shoulders alone, which look narrow on a turned body, so it came out far too big and off to one side; now it\'s sized by the face, the shoulders to the hips and the shoulders together, and laid on body to body: the piece\'s torso mapped onto theirs from shoulders to hips (its middle on their middle, its sides on their sides, its zip and pockets in proportion), each sleeve onto its own arm, the shoulders covered. Where the piece shows skin (a bare midriff under a short top), theirs shows; a belt or jeans picked with it aren\'t laid on. Upper body does this with sleeves on both too.' },
  { v: '1.99', date: '2026-11-20', notes: 'Fashion: the hair beside a made neck no longer looks chopped. The neck\'s skin ends on one smooth, continuous line down each side (its shape, or just inside where the hair comes in, smoothed down the neck), and past it is the dark behind the neck, as under the hair, so the hair\'s own ragged edge lies on dark the way it lay on the old collar. A necklace the piece\'s model wore no longer shows as a thin line across the neck.' },
  { v: '1.98', date: '2026-11-20', notes: 'Fashion: a made neck is the same color as their skin. It met the jaw\'s deep shade and carried it down the whole neck as a muddy grey-brown; now their skin\'s color is matched channel by channel (its warmth kept), its exact shade at the jaw, and lit as their skin is a little way below it; the shading that only made skin has (the chin\'s shadow, the neck\'s roundness, shade by hair) is gentler.' },
  { v: '1.97', date: '2026-11-20', notes: 'Fashion: the made neck is worked from their own skin down onto the piece, with no lines. Where it meets their skin (the jaw) it is exactly that skin, its exact shade at the edge, and the shapes only made skin has (the shadow under the chin, the neck\'s roundness, shade by hair) come in gradually away from it; beside the neck, what\'s around it (the dark behind it, their hair) is carried in instead of a shadow of its own; and the piece\'s open collar fades in over a band onto the neck, its edge soft, not cut at a row.' },
  { v: '1.96', date: '2026-11-20', notes: 'Fashion: opened after an update, the piece is placed again where it goes, without an old drag or pinch from before pushing it off (it could land at the bottom of the photo). A made neck looks like a neck: a column under the chin leaning to the shoulders, lit round (darker toward its sides), with shadow beside it, and the skin shaded where it meets hair or a deep shadow, so it sits in the picture instead of looking pasted on.' },
  { v: '1.95', date: '2026-11-20', notes: 'Fashion: more natural skin texture wherever skin is made up (a neck where a collar was taken off, a bare arm where a sleeve was, a lower neckline). It\'s now taken from many patches of the person\'s own clear skin (not one small square), with its fine detail (pores, the photo\'s grain) and a hint of real skin\'s soft mottling, laid on as a patchwork with no repeats; patches with something in them (a tattoo, a strap) and marks like moles aren\'t copied.' },
  { v: '1.94', date: '2026-11-19', notes: 'Fashion: no dark line left between the jaw and the new neck. The top edge of a black collar right under the jaw, pure black, which the person finder can take for hair, is taken off with the rest; and a few pixels of skin right along the edge that are much darker than their skin (the collar\'s shadow where it met the jaw) are made again from either side, so the jaw shades straight into the neck.' },
  { v: '1.93', date: '2026-11-19', notes: 'Fashion: skin made where the old top was taken off (a neck above an open collar, a shoulder) now grows out of their real skin wherever it touches it: the color and light of the skin it borders (the shaded underside of the jaw too) carried smoothly into it and fading out further in, so it meets their skin with no seam or flat block. In Upper body, a high dark collar rising beside the jaw is taken off too, so the neck meets the jaw itself.' },
  { v: '1.92', date: '2026-11-19', notes: 'The version number at the top right of every screen of the app (Magic, Fashion, Files, each app), not only Home; tap it for what changed and Update to Latest Version. Fashion, Upper body: each sleeve is laid on as one whole sleeve, straightened from the piece\'s arm and wrapped onto the person\'s arm across its own width (no pieces over a hand or a stripe of skin left on the arm), under hair lying beside the arm; an open collar shows their neck in the shadow under the chin, blended into it, not a dark block of the old top beside the jaw.' },
  { v: '1.91', date: '2026-11-19', notes: 'Photo Editor: 🖼 Overlay image (in Edit) lays another image over the photo you\'re editing, in layers (Collage → Free / Superimpose, your photo at the bottom). Each layer can now be edited: 🧽 Erase parts of it to show what\'s under it, 🖌 Restore brings them back (brush size and softness; undo; kept with your work and in what\'s saved), and a Layers list to pick a layer, hide or show it (👁), and move it up or down. Collage no longer risks losing work in progress when it\'s reopened.' },
  { v: '1.90', date: '2026-11-19', notes: 'Fashion, Upper body: matched body to body by both people\'s poses. Each arm of the piece (whatever of its selection lies along that arm, outside its torso) is bent onto the same arm of the person, so an arm the person finder didn\'t tell apart (one holding a glass) gets its sleeve too; the piece\'s torso is the rest, so no patch of a sleeve lands on a shoulder. A sleeve stays the width of the arm it\'s on (a little more for loose cloth) and never covers what\'s in front (a glass). Where a row of the piece is too short (its shoulders, near its hem), the nearest row that reaches is used, not its edge smeared. A black collar in the shadow under the chin is replaced too.' },
  { v: '1.89', date: '2026-11-19', notes: 'Fashion Replace (a top, a dress, Upper body) now takes off first: all of the garment worn there is found, joined or not (its side seen past a lock of hair, a strip by the armhole, between strands, down to where it really ends; never something of its color off beside them), made their bare skin (their own tone and texture, lit as their skin is), and the new piece laid on that with its own color and texture, taking only the photo\'s light and the light and shade on their skin under it. Under strands of hair the new top shows, not skin. With all of the old garment gone, the check before saving no longer has any of it to point at.' },
  { v: '1.88', date: '2026-11-19', notes: 'Fashion, Upper body (clothes + skin) with a shirt onto a different top: its torso laid in the way Top now is (only the shirt\'s cloth, not the model\'s hair or skin over it, cut at its hem, at one scale, so its pockets and buttons keep their shape); the zone carried down to where the top worn there really ends (no band of the old top left below the waist line when they\'re sitting); and each sleeve bent along both people\'s arms (shoulder, elbow, wrist), so a sleeve from a raised arm follows an arm held down instead of being pressed into its outline.' },
  { v: '1.87', date: '2026-11-19', notes: 'Fashion, a shirt onto a different top looks like that shirt: its own color, buttons, pockets and fabric, in proportion. It\'s no longer stretched to the narrow strips of the old top seen between locks of hair (which squashed it into stripes), nor run on past its hem by its bottom rows repeated (when a sliver of the pants was picked with it, it took the pants\' color): it\'s cut at its real hem and laid in at one scale by both people\'s shoulders. On a black top with long dark hair over it, the whole old top is replaced, its side by the armhole too; dark hair beside it is no longer recolored pink, and an earring by the neck is no longer erased.' },
  { v: '1.86', date: '2026-11-19', notes: 'No more zooming in on a phone, in every app (Fashion, FM, Files, Settings and the rest, and Trade Desk, Inkling, Laundry Timer and Fox Games): every text box and picker is big enough that iPhone Safari doesn\'t zoom in when one is tapped (it stayed zoomed in, cut off at the right). Pinch-zooming a photo or map still works. The decryption page fits a phone\'s width too.' },
  { v: '1.85', date: '2026-11-19', notes: 'WorldAtlas easier on a phone: bigger, clearer buttons, its tools in one row across the top (none cut off), the Go to box across the width, and no more zooming in when a box is tapped (it stayed zoomed in). Magic and Saved Files are behind their own password now, off the home screen.' },
  { v: '1.84', date: '2026-11-19', notes: 'Laundry Timer (Productivity) and Inkling (Creativity: sketch it, search it; with your own Anthropic key in its settings) in Command Center, working offline. Settings → Edit Home Screen: a switch on each app to hide it from the home screen (Show all brings them back).' },
  { v: '1.83', date: '2026-11-18', notes: 'WorldAtlas (your Minecraft Bedrock world\'s map: biomes, structures and your own markers) in Command Center, in a new Games part of the home screen with Fox Games; it works offline too.' },
  { v: '1.82', date: '2026-11-18', notes: 'Packages, a tab of Updates: add a tracking number (USPS, UPS, FedEx, DHL, Amazon, OnTrac: the carrier found from it) and follow it live, a progress bar to delivered, where it is and when it\'s expected (live status through your Worker; else a button to the carrier\'s page). Units, a unit and currency converter (rates kept for offline). The Updates card shows every game today, each opening that game, and each line opens its own tab. Settings and Edit Home Screen reorder by dragging the ☰. Settings → Suggest Improvements: notes for future updates, kept on the phone and copied to your Drive.' },
  { v: '1.81', date: '2026-11-18', notes: 'The home screen in three parts: Updates, one card with what\'s next on your calendar, the weather and your game, opening the Updates page (Calendar, Weather and Sports together, as tabs); Productivity (Notes, Files, Magic, Draw); and Creativity (Rap, Games, Trade Desk). Settings is the ⚙ at the top right, beside the version; the version history has an Update to Latest Version button too.' },
  { v: '1.80', date: '2026-11-18', notes: 'Trade Desk (the LHS fantasy football trade analyzer) on the home screen. Sports, a game\'s stats laid out like a box score: the score by quarter, then the game\'s leaders side by side as ESPN shows them (a row each for Points, Rebounds, Assists; Passing, Rushing, Receiving: each team\'s leader with their picture, name and line, its numbers bold), then team stats. Recent edits are shown in the apps they belong to (Files, the Photo Editor: a collage in progress, Magic), not on the home screen.' },
  { v: '1.79', date: '2026-11-18', notes: 'FM, a face behind bangs: when its eyes are hidden and no face is found, its shape is worked out from the skin that shows (cheeks, nose, mouth, chin), so a Character goes on it by itself; the bangs over it are found by the color of that person\'s own hair inside the face\'s shape, and the Character goes on behind them; its color and light are taken from the face\'s skin, not the hair over it.' },
  { v: '1.78', date: '2026-11-17', notes: 'Files → PDF: ➕ Add, another PDF\'s pages added at the end (two PDFs combined into one), or an image laid on a page (a logo, a stamp, a photo), dragged to move it and by its corner to size it, saved into the PDF.' },
  { v: '1.77', date: '2026-11-17', notes: 'Fashion: the old jersey seen past someone\'s arm hanging in front (between their forearm and the person beside) is taken off with the rest, not left showing; a top laid in right down to its hem on a large photo too (no pale band along the bottom); and a strip of the next person\'s jersey beside a shoulder isn\'t taken for theirs.' },
  { v: '1.76', date: '2026-11-17', notes: 'Fashion: an edit continued from before an update is worked out again by the new version (the piece, what it goes on, the waist, the placing; what you picked or brushed by hand is kept), instead of keeping what the old one found. A top\'s real hem is found the same on a large photo as on a small one (a loose jersey over the shorts of the same white too).' },
  { v: '1.75', date: '2026-11-17', notes: 'Fashion, where someone\'s arm is in front of the clothes being replaced: the old jersey right up against the arm is taken off too. Its lettering beside the arm isn\'t mistaken for the arm\'s edge, a strip of it isn\'t given to the person whose arm it is, and a pale jersey the finder took for skin beside the arm is jersey.' },
  { v: '1.74', date: '2026-11-17', notes: 'Fashion, from a real test (three jerseys): tattoos on a bare arm are skin, not clothes, and stay as they are; someone\'s shoulder hidden behind the next person\'s arm no longer takes that arm (so nothing is painted on it); a dark number by an arm in front, which the finder wasn\'t sure was cloth, is taken off with the rest, and a strip of someone\'s jersey isn\'t given to the person beside it; a top ends where it really does (tucked in at a curved waistband, or hanging loose over the shorts), and the piece\'s own hem stops above its waistband; nothing of the old color is put on the skin, an arm or the shorts below.' },
  { v: '1.73', date: '2026-11-17', notes: 'Fashion, finding each person in a group: each person\'s outline now follows their own body (their pose gives where their torso, arms, legs and head can be, so a neighbour\'s jersey, shorts or shoulder next to them isn\'t taken in) and is then snapped to the photo\'s real edges, pixel by pixel, so the outline is tight around them. Settings: every card after App version folded until tapped, and their order set with ↑ / ↓ (kept on this phone); App version stays first and open; a link to Saved Files opens its card.' },
  { v: '1.72', date: '2026-11-17', notes: 'Fashion, depth: someone in front (the next person\'s arm across a jersey) now hides the new piece the way it hid the old one: the garment goes on behind them at its full width, with them kept in front and a soft shadow where they meet it, instead of the piece being squeezed into what\'s seen; a side cut off by the photo\'s edge is laid in as going on past it; a body turned a little keeps its print where its chest is (the old garment\'s number tells where the front is). Settings: Update to Latest Version at the top; Edit Home Screen folded until tapped.' },
  { v: '1.71', date: '2026-11-17', notes: 'Fashion: text and logos on the clothes (lettering, numbers, a brand mark) keep their own shape: each is found on the piece, the cloth laid in without it, and the print put back as one rigid piece, sized, turned and placed to follow how the cloth went onto the body, so a word isn\'t stretched, squeezed or bent row by row; trims along the edges aren\'t mistaken for prints.' },
  { v: '1.70', date: '2026-11-17', notes: 'Fashion, from a real test (jerseys in a group photo): the waist found by the body\'s pose, not where the colors change (big lettering or a top and shorts of one color fooled it), so the whole top is taken and it ends at the waistband; in a group, an arm two people\'s poses both claim goes to the one it hangs from; what the finder took for skin inside clothes (a white jersey in warm light, a number\'s trim) is clothes; shorts the same color as the old top aren\'t recolored; an arm running off the photo\'s edge isn\'t taken for a sleeve; both bare-armed, an upper body swaps only the clothes, their skin untouched.' },
  { v: '1.69', date: '2026-11-14', notes: 'Fashion body zones, more real: fine strands of hair stay over the new clothes, crisp (found by their color, not only where the finder is sure); a sleeve laid over a bare arm takes the arm\'s own light and shade; the new clothes\' edges cast a faint shadow on the skin under them (a sleeve\'s hem, a strap); no haze of the piece photo\'s background at its edges; the neckline follows the piece pixel by pixel in zones too.' },
  { v: '1.68', date: '2026-11-14', notes: 'Fashion body zones: laid in by both people\'s poses (shoulders on shoulders, waist on waist); a waist line that tilts with the hips, a Waist line slider on both photos (its outline shown as you move it), and the new top\'s hem casting a soft shadow on what\'s below; rebuilt arms and necklines in the person\'s own skin texture; their own hand across their front stays in front; a check before saving points at anything that would give it away (Show me, or Save anyway).' },
  { v: '1.67', date: '2026-11-14', notes: 'Fashion: clean, natural edges with auto placement. Each edge pixel is worked out from the photo itself (how much of it was the old garment, from the colors on either side), so Replace swaps exactly that share: no rim of the old color, no blur, the photo\'s own crisp or soft edge kept. Overlay pieces lose the background they were photographed against. A collar riding up is taken off too; what\'s uncovered under a hem is filled from the pants, not skin.' },
  { v: '1.66', date: '2026-11-14', notes: 'Fashion: ➕ Add is gone (🧥 Overlay with Fit to body at 0 does it); drag moves the whole piece in Overlay and Replace, pinch sizes and turns it. FM: 👥 Best face from another shot (someone\'s eyes closed: their face from another shot of the group). Photo Editor → Clean Up: 👤 Remove a person with one tap. Home: today\'s weather and your next game at a glance, and Recent edits to continue.' },
  { v: '1.65', date: '2026-11-14', notes: 'Fashion: hidden fabric filled with its own texture; straps matched (drawn on bare shoulders, taken off for a strapless piece); the new neckline followed; sharpness and grain matched to the photo; soft shadows where hair or an arm lies over it; group photos: each person\'s pose found on them alone, and 🧍 Part of them to fix who\'s who; Lower body and Whole outfit for any outfit (shoes apart); ⭐ keep a piece to use again. Settings: Storage, what\'s kept on the phone and clearing it.' },
  { v: '1.64', date: '2026-11-14', notes: 'Fashion: sharper results — saved at full size from the piece\'s own photo, no streaks where a piece is stretched, no stair-step edges where two people meet, no specks through the new piece. Body zones: neck to waist by the body itself (not where the clothes change color), one clean outline of that person with the hair over their shoulders; both bare-armed, torso onto torso, each keeping their own arms.' },
  { v: '1.63', date: '2026-11-14', notes: 'Fashion: group photos — pick whose clothes and who to dress (tap a face or tap them); body zones take the skin too (arms, shoulders), not just what\'s worn; a dress laid in to its hem; the old garment\'s straps take the new color. Version history on the home screen.' },
  { v: '1.62', date: '2026-11-13', notes: 'Fashion: body zones tell skin from clothing part by part (a tank top onto a jacket and back).' },
  { v: '1.61', date: '2026-11-13', notes: 'Fashion: Replace lays the piece\'s design into the base\'s own garment outline; body zones (upper body, lower body, whole outfit); save fixed for large photos.' },
  { v: '1.60', date: '2026-11-13', notes: 'Fashion: realistic on real photos (solid, sized by the body, white stays white); a list of what\'s found in the photo; More edits.' },
  { v: '1.59', date: '2026-11-12', notes: 'Fashion: sleeves fitted right on larger photos.' },
  { v: '1.58', date: '2026-11-12', notes: 'Magic: Reverse Fill and Fashion as apps of their own; Reverse Fill patterns, hold to compare, open in Fashion.' },
  { v: '1.57', date: '2026-11-11', notes: 'FM: the photo\'s own forehead toward the hairline, color blotches evened out, a parted mouth closed to match.' },
  { v: '1.56', date: '2026-11-10', notes: 'Downloads: save batches packed by size; stills under each queued link; Download all smallest first, several at once.' },
  { v: '1.55', date: '2026-11-10', notes: 'Downloads: Save all in small batches so a phone doesn\'t run out of memory.' },
  { v: '1.54', date: '2026-11-10', notes: 'Downloads: Save all — every downloaded file in the queue to the phone in one go.' },
  { v: '1.53', date: '2026-11-10', notes: 'Downloads: simpler — four stills and size · length up front, the rest under More.' },
  { v: '1.52', date: '2026-11-10', notes: 'Downloads: its own app with Download, Queue and History; links checked by themselves.' },
  { v: '1.50', date: '2026-11-10', notes: 'Files → Download: a video from a link, with safeguards and a download manager.' },
  { v: '1.49', date: '2026-11-05', notes: 'Reverse Fill: no outline left around what\'s removed.' },
  { v: '1.48', date: '2026-11-05', notes: 'Swap scoring: aligned, shape and seam, on your own photos.' },
  { v: '1.47', date: '2026-11-05', notes: 'FM: no old features showing past the new face; lighting from the face\'s shape; Compare looks.' },
  { v: '1.46', date: '2026-11-05', notes: 'FM: keeps the Character\'s own mouth and pose by default.' },
  { v: '1.45', date: '2026-11-05', notes: 'FM: face-part maps, fine-tune and brush after the fit; fitting off the main thread.' },
  { v: '1.44', date: '2026-11-05', notes: 'FM: Reverse Fill with a color picker and automatic outline; skin texture, upscaling.' },
  { v: '1.43', date: '2026-11-04', notes: 'FM: dense face mesh (offline); matched sharpness and grain.' },
  { v: '1.41', date: '2026-11-04', notes: 'FM: the mouth and the light follow the face it goes on; the face toned like the base\'s skin.' },
  { v: '1.40', date: '2026-11-04', notes: 'Weather and Sports: two apps of their own on the home screen.' },
  { v: '1.39', date: '2026-11-04', notes: 'FaceMask: Quick Swap — two photos in, a finished face swap out.' },
  { v: '1.30', date: '2026-11-04', notes: 'FaceMask: cut out a face or put in a Character, fitted and blended in; a magnifier under the finger.' },
  { v: '1.27', date: '2026-10-31', notes: 'Rap app: write lyrics with next-word, complete-the-line and rhyme suggestions.' },
  { v: '1.26', date: '2026-10-31', notes: 'Cutout: a stronger patch fix, plus Wand, Brush and a magnifier.' },
  { v: '1.23', date: '2026-10-30', notes: 'Saved Files: folders, a decryption kit to open them without the app.' },
  { v: '1.21', date: '2026-10-30', notes: 'Files, Draw, QR and Calendar on the home screen; Sports as a calendar; Saved Files in Google Drive.' },
  { v: '1.18', date: '2026-10-24', notes: 'Settings app: an app-wide background color; Draw, a blank canvas.' },
  { v: '1.13', date: '2026-10-23', notes: 'Auto-Crop: find the post\'s media in feed screenshots.' },
  { v: '1.11', date: '2026-10-23', notes: 'Editor: clean-line Auto-Crop detection.' },
  { v: '1.7', date: '2026-10-17', notes: 'QR & Barcode: scan with a link safety check, make styled QR codes.' },
  { v: '1.6', date: '2026-10-17', notes: 'Editor: Collage, Superimpose and Cutout with a Characters library.' },
  { v: '1.4', date: '2026-10-17', notes: 'Photo Editor.' },
  { v: '1.0', date: '2026-10-15', notes: 'Command Center: the first version.' },
];

